	private static long[] predicates(LmdbNodePredicateIndex index, int plane, long subject) {
		long localReference = index.findLocalReference(plane, subject, new ImmutablePagedQuadCsfIndex.LookupCursor());
		if (localReference == 0) {
			return new long[0];
		}
		ImmutablePagedQuadCsfIndex.RowCursor cursor = new ImmutablePagedQuadCsfIndex.RowCursor();
		index.resolve(localReference, cursor);
		long[] predicates = new long[Math.toIntExact(cursor.edgeCount())];
		assertThat(cursor.copy(0, predicates.length, predicates, 0, null, 0)).isEqualTo(predicates.length);
		return predicates;
	}

